            r = spec.get("rule")
            if isinstance(r, dict):
                prefix = r.get("prefix")
            else:
                prefix = spec.get("prefix")
        if prefix is None:
            prefix = "err"
        kind = ""
        if isinstance(payload, dict):
            if "kind" in payload:
                kind = payload["kind"]
